v3: multipart upload has a data race and can hang after an early server response

## Summary

Resty v3 multipart streaming has two related concurrency problems when the HTTP server or `RoundTripper` returns a response before the multipart producer has finished writing the request body:

1. `Request.multipartCancelFunc` is written by the multipart writer goroutine and read/called by the request goroutine without synchronization.
2. The request can hang indefinitely while waiting for `multipartErrChan` if the source reader is already blocked inside `Read`.

This appears to be related to the multipart lifecycle introduced in #1101 while fixing #1030.

## Versions tested

- `resty.dev/v3 v3.0.0-rc.3`
- current `v3` branch, commit `ea5b6cf677568d2f22b395a9dca8b95dec43f939`
- Go 1.25.4
- darwin/arm64

Both problems reproduce on `v3.0.0-rc.3` and the current `v3` branch.

## Reproducer

`go.mod`:

```go
module resty-multipart-repro

go 1.23

require resty.dev/v3 v3.0.0-rc.3
```

`multipart_test.go`:

```go
package restyrepro

import (
	"bytes"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"resty.dev/v3"
)

func TestMultipartEarlyResponseRace(t *testing.T) {
	client := resty.NewWithClient(&http.Client{
		Transport: earlyResponseTransport{},
	})

	for range 1000 {
		_, _ = client.R().
			SetMultipartFields(&resty.MultipartField{
				Name:        "audio",
				FileName:    "audio.wav",
				ContentType: "audio/wav",
				Reader:      bytes.NewReader(make([]byte, 1<<20)),
			}).
			Post("http://resty.test/upload")
	}
}

type earlyResponseTransport struct{}

func (earlyResponseTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	// net/http allows a RoundTripper to consume and close the request body
	// asynchronously after RoundTrip returns.
	go func() {
		_, _ = io.Copy(io.Discard, req.Body)
		_ = req.Body.Close()
	}()

	return &http.Response{
		StatusCode: http.StatusUnprocessableEntity,
		Status:     "422 Unprocessable Entity",
		Header:     make(http.Header),
		Body:       io.NopCloser(strings.NewReader("rejected")),
		Request:    req,
	}, nil
}

type blockingReadCloser struct {
	started chan struct{}
	release chan struct{}
	once    sync.Once
}

func newBlockingReadCloser() *blockingReadCloser {
	return &blockingReadCloser{
		started: make(chan struct{}),
		release: make(chan struct{}),
	}
}

func (r *blockingReadCloser) Read([]byte) (int, error) {
	select {
	case <-r.started:
	default:
		close(r.started)
	}

	<-r.release

	return 0, io.EOF
}

func (r *blockingReadCloser) Close() error {
	r.once.Do(func() {
		close(r.release)
	})

	return nil
}

func TestMultipartReturnsAfterEarlyResponse(t *testing.T) {
	reader := newBlockingReadCloser()

	server := httptest.NewServer(http.HandlerFunc(
		func(w http.ResponseWriter, _ *http.Request) {
			// Ensure the multipart writer is blocked inside the source
			// Reader.Read before returning an early response.
			<-reader.started
			http.Error(w, "rejected", http.StatusUnprocessableEntity)
		},
	))
	defer server.Close()

	done := make(chan error, 1)

	go func() {
		_, err := resty.New().R().
			SetMultipartFields(&resty.MultipartField{
				Name:        "audio",
				FileName:    "audio.wav",
				ContentType: "audio/wav",
				Reader:      reader,
			}).
			Post(server.URL)

		done <- err
	}()

	select {
	case <-done:
		// The HTTP response has already arrived, so the request should
		// return without requiring the caller to unblock the reader.
	case <-time.After(time.Second):
		// Cleanup the blocked Resty multipart writer.
		_ = reader.Close()
		<-done

		t.Fatal("multipart request did not return after the server responded")
	}
}
```

